// Valida lo que manda el panel (lib/tienda-web/clientes/seguimiento.ts): { evento: 'tienda_pedido', aviso_id }.
// Solo eso: el correo y lo demás se leen de la MySQL en el nodo siguiente (el webhook es publico).
const body = $json.body || {};
const id = parseInt(body.aviso_id, 10);
if (body.evento !== 'tienda_pedido' || !(id > 0)) return null;
return { json: { id } };

// Arma el correo de seguimiento de una cotización de la tienda web con la fila de "Leer aviso"
// (tienda_pedido_avisos). Nada viene del webhook (es público): el panel guardó todo
// (lib/tienda-web/clientes/seguimiento.ts). Sin fila = ya se mandó o tiene más de un día.
const a = $json;
if (!a || !a.id) return null;
const para = String(a.correo || '').trim();
if (!/^[^\s@<>,;"']+@[^\s@<>,;"']+\.[a-z]{2,}$/i.test(para)) return null;

const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, (x) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[x]));
const numero = String(a.numero || '');
const vendedor = String(a.vendedor || '').trim() || 'Tu vendedor';
const monto = a.total != null && Number(a.total) > 0
  ? (String(a.moneda || 'USD') === 'USD' ? '$' : String(a.moneda) + ' ') + Number(a.total).toLocaleString('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
  : '';
const enlace = /^https:\/\/[^\s"'<>]+$/.test(String(a.enlace || '')) ? String(a.enlace) : '';

const TEXTOS = {
  lista: {
    asunto: 'Tu cotización ' + numero + ' está lista',
    titulo: 'Tu cotización está lista',
    cuerpo: vendedor + ' te envió la cotización ' + numero + ' con los precios finales' + (monto ? ' (total ' + monto + ')' : '') + '. Si estás de acuerdo, acéptala en Mi cuenta con un clic y se confirma como pedido.',
    boton: 'Ver y aceptar',
  },
  confirmada: {
    asunto: 'Tu pedido ' + numero + ' está confirmado',
    titulo: 'Pedido confirmado',
    cuerpo: 'Tu pedido ' + numero + (monto ? ' por ' + monto : '') + ' está confirmado. ' + vendedor + ' lo prepara y te avisamos cuando salga.',
    boton: 'Ver mi pedido',
  },
  despachada: {
    asunto: 'Tu pedido ' + numero + ' salió',
    titulo: 'Tu pedido va en camino',
    cuerpo: 'El pedido ' + numero + ' ya salió del almacén. En Mi cuenta ves el despacho y sus productos.',
    boton: 'Ver el despacho',
  },
  facturada: {
    asunto: 'Tu pedido ' + numero + ' fue facturado',
    titulo: 'Pedido facturado',
    cuerpo: 'El pedido ' + numero + ' ya tiene su factura. La ves en Mi cuenta, en el pedido y en tu estado de cuenta.',
    boton: 'Ver la factura',
  },
  anulada: {
    asunto: 'Tu cotización ' + numero + ' fue anulada',
    titulo: 'Cotización anulada',
    cuerpo: 'La cotización ' + numero + ' se anuló. Si no lo esperabas, escríbele a ' + (vendedor === 'Tu vendedor' ? 'tu vendedor' : vendedor) + '.',
    boton: 'Ver en Mi cuenta',
  },
};
const t = TEXTOS[a.aviso];
if (!t) return null;

const html = '<!doctype html><html><body style="margin:0;background:#F4F5F2;font-family:Arial,Helvetica,sans-serif;color:#0B0D12">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F5F2;padding:24px 12px"><tr><td align="center">'
  + '<table role="presentation" width="520" cellpadding="0" cellspacing="0" style="max-width:520px;width:100%;background:#FFFFFF;border:1px solid #E0E2DB;border-radius:16px">'
  + '<tr><td style="padding:32px 32px 8px"><p style="margin:0;font-size:20px;font-weight:bold;letter-spacing:-.01em">SUPRICOM</p>'
  + '<p style="margin:18px 0 0;font-size:13px;font-weight:bold;letter-spacing:.06em;color:#1D4ED8">' + esc(numero) + (a.sede ? ' · SEDE ' + esc(String(a.sede).toUpperCase()) : '') + '</p>'
  + '<h1 style="margin:6px 0 8px;font-size:22px;line-height:1.3">' + esc(t.titulo) + '</h1>'
  + '<p style="margin:0;font-size:15px;line-height:1.55;color:#565C68">' + esc(t.cuerpo) + '</p></td></tr>'
  + (enlace ? '<tr><td style="padding:22px 32px 8px"><a href="' + esc(enlace) + '" style="display:inline-block;padding:13px 22px;border-radius:999px;background:#0B0D12;color:#FFFFFF;font-size:15px;font-weight:bold;text-decoration:none">' + esc(t.boton) + '</a></td></tr>' : '')
  + '<tr><td style="padding:18px 32px 28px"><p style="margin:0;font-size:12px;line-height:1.5;color:#565C68">Te escribimos porque enviaste esta cotización desde la tienda de SUPRICOM. Para cualquier cambio, responde a tu vendedor.</p></td></tr>'
  + '</table></td></tr></table></body></html>';
const texto = ['SUPRICOM · ' + t.titulo, '', t.cuerpo, '', enlace ? t.boton + ': ' + enlace : ''].join('\n');

const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const partir = (s) => s.replace(/.{1,76}/g, (l) => l + '\r\n');
const limite = 'pedido-' + a.id + '-' + Date.now().toString(36);
const mime = [
  'From: =?UTF-8?B?' + b64('Tienda web SUPRICOM') + '?= <dmedina@supricom.com.ve>',
  'To: ' + para,
  'Subject: =?UTF-8?B?' + b64(t.asunto) + '?=',
  'MIME-Version: 1.0',
  'Content-Type: multipart/alternative; boundary="' + limite + '"',
  '',
  '--' + limite,
  'Content-Type: text/plain; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  partir(b64(texto)),
  '--' + limite,
  'Content-Type: text/html; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  partir(b64(html)),
  '--' + limite + '--',
  '',
].join('\r\n');
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

return { json: { aviso_id: Number(a.id), para, asunto: t.asunto, raw } };
